from array import array
class Solution:
    def countMagicalPairs(self, s: str) -> int:
        n = len(s)
        def counts_ending(text):
            table = [array("I", [0]) * n for _ in range(27)]
            last = [-1] * 26
            for end, ch in enumerate(text):
                last[ord(ch) - 97] = end
                positions = sorted((p for p in last if p >= 0), reverse=True)
                for i, position in enumerate(positions):
                    following = positions[i + 1] if i + 1 < len(positions) else -1
                    table[i + 1][end] = position - following
            return table
        left = counts_ending(s)
        right = counts_ending(s[::-1])
        return sum(sum(left[d][split] * right[d][n - split - 2] for d in range(1, 27)) for split in range(n - 1))
